import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { join, extname } from 'node:path';

const port = Number(process.env.PORT || 8080);
const dbPath = process.env.DB_PATH || './workboard.sqlite';
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  archived INTEGER NOT NULL DEFAULT 0,
  default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))
);
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High')),
  due_date TEXT
)`);
try { db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch {}
try { db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal'"); } catch {}
try { db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal'"); } catch {}
try { db.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT'); } catch {}
try { db.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''"); } catch {}
db.exec(`CREATE TABLE IF NOT EXISTS task_positions (
  task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  PRIMARY KEY (task_id, project_id)
);
INSERT OR IGNORE INTO task_positions (task_id, project_id, position)
  SELECT id, project_id, id FROM tasks;
`);
const root = new URL('.', import.meta.url).pathname;
const mime = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };

function json(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  if (req.method === 'GET' && url.pathname === '/health') return json(res, 200, { status: 'ok' });
  if (req.method === 'GET' && url.pathname === '/api/projects') {
    return json(res, 200, db.prepare(`SELECT p.id, p.name, p.archived, p.default_priority,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id=p.id AND t.completed=1) AS completed_count,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id=p.id) AS total_count
      FROM projects p ORDER BY p.id`).all());
  }
  if (req.method === 'POST' && url.pathname === '/api/projects') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return json(res, 400, { error: 'Invalid JSON' }); }
    const name = typeof data.name === 'string' ? data.name.trim() : '';
    if (!name) return json(res, 400, { error: 'Project name is required' });
    const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return json(res, 201, { id: Number(result.lastInsertRowid), name });
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/archive$/);
  if (archiveMatch && req.method === 'PATCH') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return json(res, 400, { error: 'Invalid JSON' }); }
    if (typeof data.archived !== 'boolean') return json(res, 400, { error: 'Invalid archive state' });
    const result = db.prepare('UPDATE projects SET archived=? WHERE id=?').run(data.archived ? 1 : 0, Number(archiveMatch[1]));
    return result.changes ? json(res, 200, { ok: true }) : json(res, 404, { error: 'Project not found' });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && req.method === 'GET') {
    const projectId = Number(tasksMatch[1]);
    if (!db.prepare('SELECT 1 FROM projects WHERE id = ?').get(projectId)) return json(res, 404, { error: 'Project not found' });
    return json(res, 200, db.prepare(`SELECT t.id, t.title, t.completed, t.priority, t.due_date, t.notes
      FROM tasks t JOIN task_positions p ON p.task_id=t.id AND p.project_id=t.project_id
      WHERE t.project_id = ? ORDER BY p.position, t.id`).all(projectId));
  }
  if (tasksMatch && req.method === 'POST') {
    const projectId = Number(tasksMatch[1]);
    if (!db.prepare('SELECT 1 FROM projects WHERE id = ?').get(projectId)) return json(res, 404, { error: 'Project not found' });
    const owner = db.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (owner?.archived) return json(res, 403, { error: 'Project is archived' });
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return json(res, 400, { error: 'Invalid JSON' }); }
    const title = typeof data.title === 'string' ? data.title.trim() : '';
    if (!title) return json(res, 400, { error: 'Task title is required' });
    const priority = db.prepare('SELECT default_priority FROM projects WHERE id=?').get(projectId).default_priority;
    const result = db.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)').run(projectId, title, priority);
    const taskId = Number(result.lastInsertRowid);
    const nextPosition = db.prepare('SELECT COALESCE(MAX(position), 0) + 1 AS position FROM task_positions WHERE project_id=?').get(projectId).position;
    db.prepare('INSERT INTO task_positions (task_id, project_id, position) VALUES (?, ?, ?)').run(taskId, projectId, nextPosition);
    return json(res, 201, { id: Number(result.lastInsertRowid), title, completed: 0, priority });
  }
  const moveMatch = url.pathname.match(/^\/api\/tasks\/(\d+)\/move$/);
  if (moveMatch && req.method === 'PATCH') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return json(res, 400, { error: 'Invalid JSON' }); }
    const taskId = Number(moveMatch[1]);
    const task = db.prepare('SELECT project_id FROM tasks WHERE id=?').get(taskId);
    if (!task) return json(res, 404, { error: 'Task not found' });
    if (db.prepare('SELECT archived FROM projects WHERE id=?').get(task.project_id)?.archived) return json(res, 403, { error: 'Project is archived' });
    const destination = db.prepare('SELECT id FROM projects WHERE id=? AND archived=0').get(Number(data.destination_id));
    if (!destination || destination.id === task.project_id) return json(res, 400, { error: 'Invalid destination project' });
    const remembered = db.prepare('SELECT 1 FROM task_positions WHERE task_id=? AND project_id=?').get(taskId, destination.id);
    if (!remembered) {
      const nextPosition = db.prepare('SELECT COALESCE(MAX(position), 0) + 1 AS position FROM task_positions WHERE project_id=?').get(destination.id).position;
      db.prepare('INSERT INTO task_positions (task_id, project_id, position) VALUES (?, ?, ?)').run(taskId, destination.id, nextPosition);
    }
    db.prepare('UPDATE tasks SET project_id=? WHERE id=?').run(destination.id, taskId);
    return json(res, 200, { ok: true });
  }
  const taskMatch = url.pathname.match(/^\/api\/tasks\/(\d+)$/);
  if (taskMatch && req.method === 'PATCH') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return json(res, 400, { error: 'Invalid JSON' }); }
    const task = db.prepare('SELECT project_id FROM tasks WHERE id=?').get(Number(taskMatch[1]));
    if (!task) return json(res, 404, { error: 'Task not found' });
    if (db.prepare('SELECT archived FROM projects WHERE id=?').get(task.project_id)?.archived) return json(res, 403, { error: 'Project is archived' });
    if (Object.hasOwn(data, 'notes')) {
      if (typeof data.notes !== 'string') return json(res, 400, { error: 'Invalid notes' });
      db.prepare('UPDATE tasks SET notes=? WHERE id=?').run(data.notes, Number(taskMatch[1]));
      return json(res, 200, { ok: true, notes: data.notes });
    }
    if (Object.hasOwn(data, 'due_date')) {
      const raw = typeof data.due_date === 'string' ? data.due_date.trim() : '';
      let dueDate = null;
      if (raw) {
        const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
        if (!match) return json(res, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
        const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
        const date = new Date(0);
        date.setUTCHours(0, 0, 0, 0);
        date.setUTCFullYear(year, month - 1, day);
        if (year < 1 || date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) return json(res, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
        dueDate = raw;
      }
      db.prepare('UPDATE tasks SET due_date=? WHERE id=?').run(dueDate, Number(taskMatch[1]));
      return json(res, 200, { ok: true, due_date: dueDate });
    }
    if (typeof data.priority === 'string') {
      if (!['Low', 'Normal', 'High'].includes(data.priority)) return json(res, 400, { error: 'Invalid priority' });
      db.prepare('UPDATE tasks SET priority=? WHERE id=?').run(data.priority, Number(taskMatch[1]));
      return json(res, 200, { ok: true, priority: data.priority });
    }
    if (typeof data.title === 'string') {
      const title = data.title.trim();
      if (!title) return json(res, 400, { error: 'Task title is required' });
      db.prepare('UPDATE tasks SET title=? WHERE id=?').run(title, Number(taskMatch[1]));
      return json(res, 200, { ok: true, title });
    }
    if (typeof data.completed !== 'boolean') return json(res, 400, { error: 'Invalid completion state' });
    db.prepare('UPDATE tasks SET completed=? WHERE id=?').run(data.completed ? 1 : 0, Number(taskMatch[1]));
    return json(res, 200, { ok: true });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (req.method === 'PATCH' && projectMatch) {
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return json(res, 400, { error: 'Invalid JSON' }); }
    const id = Number(projectMatch[1]);
    const project = db.prepare('SELECT archived FROM projects WHERE id=?').get(id);
    if (!project) return json(res, 404, { error: 'Project not found' });
    if (project.archived) return json(res, 403, { error: 'Project is archived' });
    if (typeof data.default_priority === 'string') {
      if (!['Low', 'Normal', 'High'].includes(data.default_priority)) return json(res, 400, { error: 'Invalid priority' });
      db.prepare('UPDATE projects SET default_priority=? WHERE id=?').run(data.default_priority, id);
      return json(res, 200, { ok: true, default_priority: data.default_priority });
    }
    const name = typeof data.name === 'string' ? data.name.trim() : '';
    if (!name) return json(res, 400, { error: 'Project name is required' });
    db.prepare('UPDATE projects SET name=? WHERE id=?').run(name, id);
    return json(res, 200, { ok: true, name });
  }
  if (req.method === 'GET' && projectMatch) {
    const project = db.prepare('SELECT id, name, archived, default_priority FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    return project ? json(res, 200, project) : json(res, 404, { error: 'Project not found' });
  }
  if (req.method === 'GET') {
    const file = url.pathname === '/' || url.pathname.startsWith('/projects/') ? 'index.html' : url.pathname.slice(1);
    try {
      const content = await readFile(join(root, 'public', file));
      res.writeHead(200, { 'Content-Type': mime[extname(file)] || 'application/octet-stream' });
      return res.end(content);
    } catch {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      return res.end('Not found');
    }
  }
  json(res, 404, { error: 'Not found' });
});
server.listen(port, '0.0.0.0');

const list = document.querySelector('#project-list');
const detail = document.querySelector('#project-detail');
const alertBox = document.querySelector('#alert');
let appliedProjectQuery = '';
let appliedTaskQuery = '';

function normalizeSearch(value) {
  return value.replace(/[ \t]+/g, ' ').replace(/[A-Z]/g, character => character.toLowerCase());
}

async function loadProjects() {
  const response = await fetch('/api/projects');
  const projects = await response.json();
  const filter = document.querySelector('#project-filter').value;
  const query = normalizeSearch(appliedProjectQuery);
  const container = document.querySelector('#projects');
  container.replaceChildren();
  for (const project of projects) {
    if (Boolean(project.archived) !== (filter === 'Archived')) continue;
    if (!normalizeSearch(project.name).includes(query)) continue;
    const row = document.createElement('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const button = document.createElement('button');
    button.type = 'button';
    button.textContent = 'Open project';
    button.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
    const summary = document.createElement('span');
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completed_count}/${project.total_count} completed`;
    const archive = document.createElement('button');
    archive.type = 'button';
    archive.textContent = project.archived ? 'Restore project' : 'Archive project';
    archive.addEventListener('click', async () => {
      await fetch(`/api/projects/${project.id}/archive`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived: !project.archived }) });
      await loadProjects();
    });
    row.append(name, summary, button, archive);
    container.append(row);
  }
}

let appliedDueRange = { from: '', through: '' };

function validCalendarDate(value) {
  const match = value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return false;
  const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

async function loadTasks(projectId) {
  const response = await fetch(`/api/projects/${projectId}/tasks`);
  if (!response.ok) return;
  const tasks = await response.json();
  const projectsResponse = await fetch('/api/projects');
  const activeProjects = (await projectsResponse.json()).filter(project => !project.archived && project.id !== Number(projectId));
  const filter = document.querySelector('#task-filter').value;
  const priorityFilter = document.querySelector('#priority-filter').value;
  const container = document.querySelector('#tasks');
  container.replaceChildren();
  for (const task of tasks) {
    if ((filter === 'Open' && task.completed) || (filter === 'Completed' && !task.completed)) continue;
    if (priorityFilter !== 'All' && task.priority !== priorityFilter) continue;
    if (!normalizeSearch(task.title).includes(normalizeSearch(appliedTaskQuery))) continue;
    if (appliedDueRange.from || appliedDueRange.through) {
      if (!task.due_date) continue;
      if (appliedDueRange.from && task.due_date < appliedDueRange.from) continue;
      if (appliedDueRange.through && task.due_date > appliedDueRange.through) continue;
    }
    const row = document.createElement('div');
    row.className = 'task-row';
    row.dataset.testid = 'task-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = Boolean(task.completed);
    checkbox.disabled = Boolean(document.querySelector('#archived-label').hidden === false);
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      await fetch(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
      await loadTasks(projectId);
    });
    const renameInput = document.createElement('input');
    renameInput.type = 'text';
    renameInput.setAttribute('aria-label', 'New task title');
    renameInput.value = task.title;
    renameInput.disabled = checkbox.disabled;
    const renameButton = document.createElement('button');
    renameButton.type = 'button';
    renameButton.textContent = 'Rename task';
    renameButton.disabled = checkbox.disabled;
    renameButton.addEventListener('click', async () => {
      const alert = document.querySelector('#task-alert');
      const newTitle = renameInput.value.trim();
      if (!newTitle) { alert.textContent = 'Task title is required'; alert.hidden = false; return; }
      alert.hidden = true;
      const response = await fetch(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: newTitle }) });
      if (response.ok) await loadTasks(projectId);
    });
    const priority = document.createElement('select');
    priority.setAttribute('aria-label', 'Task priority');
    for (const value of ['Low', 'Normal', 'High']) {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = value;
      priority.append(option);
    }
    priority.value = task.priority || 'Normal';
    priority.disabled = checkbox.disabled;
    priority.addEventListener('change', async () => {
      const response = await fetch(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ priority: priority.value }) });
      await loadTasks(projectId);
    });
    const dueDate = document.createElement('input');
    dueDate.type = 'text';
    dueDate.setAttribute('aria-label', 'Task due date');
    dueDate.value = task.due_date || '';
    dueDate.disabled = checkbox.disabled;
    const saveDate = document.createElement('button');
    saveDate.type = 'button';
    saveDate.textContent = 'Save due date';
    saveDate.disabled = checkbox.disabled;
    saveDate.addEventListener('click', async () => {
      const alert = document.querySelector('#task-alert');
      const response = await fetch(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ due_date: dueDate.value }) });
      if (!response.ok) { alert.textContent = 'Due date must be a valid YYYY-MM-DD date'; alert.hidden = false; return; }
      alert.hidden = true;
      await loadTasks(projectId);
    });
    const destination = document.createElement('select');
    destination.setAttribute('aria-label', 'Destination project');
    for (const project of activeProjects) {
      const option = document.createElement('option');
      option.value = project.id;
      option.textContent = project.name;
      destination.append(option);
    }
    const moveButton = document.createElement('button');
    moveButton.type = 'button';
    moveButton.textContent = 'Move task';
    destination.disabled = checkbox.disabled || activeProjects.length === 0;
    moveButton.disabled = checkbox.disabled || activeProjects.length === 0;
    moveButton.addEventListener('click', async () => {
      const response = await fetch(`/api/tasks/${task.id}/move`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ destination_id: Number(destination.value) }) });
      if (response.ok) await loadTasks(projectId);
    });
    const notes = document.createElement('textarea');
    notes.setAttribute('aria-label', 'Task notes');
    notes.value = task.notes || '';
    notes.disabled = checkbox.disabled;
    const saveNotes = document.createElement('button');
    saveNotes.type = 'button';
    saveNotes.textContent = 'Save notes';
    saveNotes.disabled = checkbox.disabled;
    saveNotes.addEventListener('click', async () => {
      const response = await fetch(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ notes: notes.value }) });
      if (response.ok) await loadTasks(projectId);
    });
    row.append(title, checkbox, renameInput, renameButton, priority, dueDate, saveDate, notes, saveNotes, destination, moveButton);
    container.append(row);
  }
}

async function render() {
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (match) {
    appliedDueRange = { from: '', through: '' };
    document.querySelector('#due-from').value = '';
    document.querySelector('#due-through').value = '';
    document.querySelector('#range-alert').hidden = true;
    appliedTaskQuery = '';
    document.querySelector('#task-search').value = '';
    const response = await fetch(`/api/projects/${match[1]}`);
    if (response.ok) {
      const project = await response.json();
      document.querySelector('#project-title').textContent = project.name;
      document.querySelector('#archived-label').hidden = !project.archived;
      const defaultPriority = document.querySelector('#default-task-priority');
      defaultPriority.value = project.default_priority || 'Normal';
      defaultPriority.disabled = Boolean(project.archived);
      document.querySelector('#rename-form').querySelectorAll('input, button').forEach(control => { control.disabled = Boolean(project.archived); });
      document.querySelector('#task-form').querySelectorAll('input, button').forEach(control => { control.disabled = Boolean(project.archived); });
      list.hidden = true;
      detail.hidden = false;
      await loadTasks(project.id);
      return;
    }
  }
  detail.hidden = true;
  list.hidden = false;
  await loadProjects();
}

document.querySelector('#create-form').addEventListener('submit', async event => {
  event.preventDefault();
  const input = document.querySelector('#project-name');
  const name = input.value.trim();
  if (!name) {
    alertBox.textContent = 'Project name is required';
    alertBox.hidden = false;
    return;
  }
  alertBox.hidden = true;
  const response = await fetch('/api/projects', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
  });
  if (response.ok) {
    input.value = '';
    await loadProjects();
  }
});
document.querySelector('#rename-form').addEventListener('submit', async event => {
  event.preventDefault();
  const input = document.querySelector('#new-project-name');
  const alert = document.querySelector('#rename-alert');
  const name = input.value.trim();
  if (!name) { alert.textContent = 'Project name is required'; alert.hidden = false; return; }
  alert.hidden = true;
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (!match) return;
  const response = await fetch(`/api/projects/${match[1]}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
  if (response.ok) {
    input.value = '';
    document.querySelector('#project-title').textContent = name;
  }
});
document.querySelector('#default-task-priority').addEventListener('change', async event => {
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (!match) return;
  const response = await fetch(`/api/projects/${match[1]}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ default_priority: event.target.value }) });
  if (!response.ok) render();
});
document.querySelector('#due-range-form').addEventListener('submit', async event => {
  event.preventDefault();
  const alert = document.querySelector('#range-alert');
  const from = document.querySelector('#due-from').value.trim();
  const through = document.querySelector('#due-through').value.trim();
  if ((from && !validCalendarDate(from)) || (through && !validCalendarDate(through))) {
    alert.textContent = 'Due range must use valid YYYY-MM-DD dates';
    alert.hidden = false;
    return;
  }
  if (from && through && from > through) {
    alert.textContent = 'Due from must not be after Due through';
    alert.hidden = false;
    return;
  }
  alert.hidden = true;
  appliedDueRange = { from, through };
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (match) await loadTasks(match[1]);
});
document.querySelector('#back').addEventListener('click', () => { appliedProjectQuery = ''; document.querySelector('#project-search').value = ''; location.href = '/'; });
document.querySelector('#project-filter').addEventListener('change', loadProjects);
document.querySelector('#project-search-form').addEventListener('submit', async event => { event.preventDefault(); appliedProjectQuery = document.querySelector('#project-search').value.trim(); await loadProjects(); });
document.querySelector('#task-search-form').addEventListener('submit', async event => { event.preventDefault(); appliedTaskQuery = document.querySelector('#task-search').value.trim(); const match = location.pathname.match(/^\/projects\/(\d+)\/?$/); if (match) await loadTasks(match[1]); });
for (const filterId of ['#task-filter', '#priority-filter']) {
  document.querySelector(filterId).addEventListener('change', () => {
    const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
    if (match) loadTasks(match[1]);
  });
}
document.querySelector('#task-form').addEventListener('submit', async event => {
  event.preventDefault();
  const input = document.querySelector('#task-title');
